const express = require('express');
const http = require('http');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const { Server } = require('socket.io');
const Database = require('better-sqlite3');
const multer = require('multer');

const PORT = process.env.PORT || 3000;
const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
const UPLOADS = path.join(DATA_DIR, 'uploads');
fs.mkdirSync(UPLOADS, { recursive: true });
const bk = require('./backup');

// ---------- Veritabanı (hiçbir şey otomatik silinmez) ----------
const db = new Database(path.join(DATA_DIR, 'app.db'));
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');
db.exec(`
CREATE TABLE IF NOT EXISTS users(
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE COLLATE NOCASE NOT NULL,
  bio TEXT DEFAULT '',
  avatar TEXT,
  token TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS follows(
  follower INTEGER NOT NULL,
  followee INTEGER NOT NULL,
  PRIMARY KEY(follower, followee)
);
CREATE TABLE IF NOT EXISTS convs(
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type TEXT NOT NULL,
  name TEXT,
  dm_key TEXT UNIQUE,
  created_by INTEGER,
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS members(
  conv_id INTEGER NOT NULL,
  user_id INTEGER NOT NULL,
  left INTEGER DEFAULT 0,
  PRIMARY KEY(conv_id, user_id)
);
CREATE TABLE IF NOT EXISTS messages(
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  conv_id INTEGER NOT NULL,
  sender_id INTEGER NOT NULL,
  kind TEXT NOT NULL,
  text TEXT,
  file TEXT,
  file_name TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_msg_conv ON messages(conv_id, id);
CREATE TABLE IF NOT EXISTS stories(
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  kind TEXT NOT NULL,
  file TEXT NOT NULL,
  caption TEXT,
  created_at INTEGER NOT NULL
);
`);

// Eski sürümden kalan bir yedek geri yüklendiyse eksik sütunları ekle (veri silinmez)
function ensureColumn(table, col, ddl) {
  const cols = db.prepare(`PRAGMA table_info(${table})`).all().map((c) => c.name);
  if (!cols.includes(col)) {
    db.exec(`ALTER TABLE ${table} ADD COLUMN ${col} ${ddl}`);
    console.log(`Veritabanı güncellendi: ${table}.${col} eklendi.`);
  }
}
ensureColumn('users', 'bio', "TEXT DEFAULT ''");
ensureColumn('users', 'avatar', 'TEXT');
ensureColumn('messages', 'file', 'TEXT');
ensureColumn('messages', 'file_name', 'TEXT');
ensureColumn('stories', 'kind', "TEXT NOT NULL DEFAULT 'image'");
ensureColumn('stories', 'caption', 'TEXT');

// ---------- Yardımcılar ----------
// Hata sebebini kısa ve dosya yolu içermeden yazar (ekranda "Sunucu hatası (...)" olarak görünür)
const describe = (e) => {
  const msg = String((e && e.message) || e || '').replace(/\/[^\s'"]+/g, '…').slice(0, 140);
  return [e && (e.code || e.name), msg].filter(Boolean).join(': ');
};
const now = () => Date.now();
const DAY = 24 * 60 * 60 * 1000;
const publicUser = (u) => u && { id: u.id, username: u.username, bio: u.bio, avatar: u.avatar };
const getUser = (id) => db.prepare('SELECT * FROM users WHERE id=?').get(id);
const isFollowing = (a, b) => !!db.prepare('SELECT 1 FROM follows WHERE follower=? AND followee=?').get(a, b);
const mutual = (a, b) => isFollowing(a, b) && isFollowing(b, a);
const isActiveMember = (conv, user) =>
  !!db.prepare('SELECT 1 FROM members WHERE conv_id=? AND user_id=? AND left=0').get(conv, user);
const isAnyMember = (conv, user) =>
  !!db.prepare('SELECT 1 FROM members WHERE conv_id=? AND user_id=?').get(conv, user);
const activeMemberIds = (conv) =>
  db.prepare('SELECT user_id FROM members WHERE conv_id=? AND left=0').all(conv).map((r) => r.user_id);

function kindFromMime(m = '') {
  if (m.startsWith('image/')) return 'image';
  if (m.startsWith('video/')) return 'video';
  if (m.startsWith('audio/')) return 'audio';
  return 'file';
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    try { fs.mkdirSync(UPLOADS, { recursive: true }); cb(null, UPLOADS); } catch (e) { cb(e); }
  },
  filename: (req, file, cb) => {
    const ext = path.extname(String(file.originalname || '')).replace(/[^.\w]/g, '').slice(0, 10);
    cb(null, crypto.randomBytes(16).toString('hex') + ext);
  },
});
const upload = multer({ storage, limits: { fileSize: 200 * 1024 * 1024 } });
// Yüklenen dosyayı bulut yedeğine de koy (cevap vermeden önce, böylece kaybolmaz)
const mirror = (req, res, next) => {
  if (!req.file) return next();
  bk.putUpload(req.file.filename).then(() => next(), (e) => { console.error('Dosya yedeklenemedi', e.message); next(); });
};

const app = express();
const server = http.createServer(app);
// Render'ın proxy'si arada 502 vermesin diye bağlantıları açık tut
server.keepAliveTimeout = 120 * 1000;
server.headersTimeout = 125 * 1000;
process.on('unhandledRejection', (e) => console.error('unhandledRejection', e));
process.on('uncaughtException', (e) => console.error('uncaughtException', e));
const io = new Server(server, { maxHttpBufferSize: 1e6 });

app.get('/healthz', (req, res) => res.send('ok'));
app.use(express.json({ limit: '1mb' }));
// Dosya yerelde yoksa (sunucu sıfırlandıysa) yedekten getir
app.use('/uploads', (req, res, next) => {
  let name = '';
  try { name = path.basename(decodeURIComponent(req.path)); } catch { return next(); }
  if (!bk.enabled || !name || fs.existsSync(path.join(UPLOADS, name))) return next();
  bk.fetchUpload(name).then(() => next(), () => next());
});
app.use(
  '/uploads',
  express.static(UPLOADS, {
    setHeaders(res) {
      res.setHeader('X-Content-Type-Options', 'nosniff');
      res.setHeader('Content-Security-Policy', 'sandbox');
    },
  })
);
// Sayfa dosyası bulunamazsa kullanılan gömülü kopya
const EMBEDDED_HTML = Buffer.from('', 'base64').toString('utf8');
// Sayfa: public/index.html; yanlışlıkla ana klasöre yüklendiyse (index.html / "index (2).html" vb.) onu da bulur
const PUBLIC_DIR = path.join(__dirname, 'public');
if (fs.existsSync(path.join(PUBLIC_DIR, 'index.html'))) {
  app.use(express.static(PUBLIC_DIR));
} else {
  const page = fs.readdirSync(__dirname).find((f) => /^index.*\.html$/i.test(f));
  console.warn('public/index.html yok, yedek sayfa: ' + page);
  app.get('/', (req, res) => (page ? res.sendFile(path.join(__dirname, page)) : res.type('html').send(EMBEDDED_HTML)));
}

// ---------- Kimlik doğrulama ----------
function auth(req, res, next) {
  const t = req.get('x-token');
  const u = t && db.prepare('SELECT * FROM users WHERE token=?').get(t);
  if (!u) return res.status(401).json({ error: 'Giriş yapmalısın' });
  req.user = u;
  next();
}
const wrap = (fn) => (req, res) => {
  try {
    fn(req, res);
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: 'Sunucu hatası (' + describe(e) + ')' });
  }
};

app.post('/api/register', wrap((req, res) => {
  const username = String(req.body.username || '').trim();
  if (!/^[\p{L}\p{N}_.]{2,20}$/u.test(username))
    return res.status(400).json({ error: 'İsim 2-20 karakter olmalı (harf, rakam, _ veya .)' });
  if (db.prepare('SELECT 1 FROM users WHERE username=?').get(username))
    return res.status(409).json({ error: 'Bu isim alınmış, başka seç' });
  const token = crypto.randomBytes(24).toString('hex');
  const r = db.prepare('INSERT INTO users(username,token,created_at) VALUES(?,?,?)').run(username, token, now());
  res.json({ token, user: publicUser(getUser(r.lastInsertRowid)) });
}));

// Başka cihazdan giriş: isim + giriş kodu
app.post('/api/login', wrap((req, res) => {
  const u = db.prepare('SELECT * FROM users WHERE username=?').get(String(req.body.username || '').trim());
  if (!u || u.token !== String(req.body.token || '').trim())
    return res.status(401).json({ error: 'İsim veya giriş kodu yanlış' });
  res.json({ token: u.token, user: publicUser(u) });
}));

// Arama için STUN/TURN ayarları (TURN_URL, TURN_USER, TURN_PASS ortam değişkenleri ile)
app.get('/api/ice', auth, wrap((req, res) => {
  const iceServers = [{ urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302'] }];
  if (process.env.TURN_URL)
    iceServers.push({ urls: process.env.TURN_URL.split(','), username: process.env.TURN_USER, credential: process.env.TURN_PASS });
  res.json({ iceServers });
}));

app.get('/api/me', auth, wrap((req, res) => res.json({ user: publicUser(req.user), token: req.user.token })));

app.put('/api/profile', auth, wrap((req, res) => {
  const bio = String(req.body.bio || '').slice(0, 200);
  db.prepare('UPDATE users SET bio=? WHERE id=?').run(bio, req.user.id);
  res.json({ ok: true });
}));

app.post('/api/avatar', auth, upload.single('file'), mirror, wrap((req, res) => {
  if (!req.file || !req.file.mimetype.startsWith('image/')) return res.status(400).json({ error: 'Fotoğraf seç' });
  const url = '/uploads/' + req.file.filename;
  db.prepare('UPDATE users SET avatar=? WHERE id=?').run(url, req.user.id);
  res.json({ avatar: url });
}));

// ---------- GIF arama (GIPHY; GIPHY_KEY yoksa kullanıcıya bilgi verilir) ----------
app.get('/api/gifs', auth, wrap(async (req, res) => {
  const key = process.env.GIPHY_KEY;
  if (!key) return res.json({ error: 'GIF arama kapalı. Yönetici GIPHY_KEY eklemeli; şimdilik "Cihazdan GIF seç" ile GIF gönderebilirsin.' });
  const q = String(req.query.q || '').trim().slice(0, 60);
  const url = q
    ? 'https://api.giphy.com/v1/gifs/search?limit=24&rating=pg-13&q=' + encodeURIComponent(q) + '&api_key=' + key
    : 'https://api.giphy.com/v1/gifs/trending?limit=24&rating=pg-13&api_key=' + key;
  const r = await fetch(url);
  if (!r.ok) return res.json({ error: 'GIF servisi şu an cevap vermiyor (' + r.status + ')' });
  const j = await r.json();
  const items = (j.data || []).map((g) => ({
    preview: g.images.fixed_width_small ? g.images.fixed_width_small.url : g.images.fixed_width.url,
    url: (g.images.fixed_height || g.images.original).url,
  }));
  res.json({ items });
}));

// ---------- Kullanıcılar / takip ----------
function userCard(me, u) {
  return {
    ...publicUser(u),
    following: isFollowing(me, u.id),
    followsMe: isFollowing(u.id, me),
  };
}

app.get('/api/users', auth, wrap((req, res) => {
  const q = String(req.query.q || '').trim();
  const rows = q
    ? db.prepare('SELECT * FROM users WHERE username LIKE ? AND id!=? ORDER BY username LIMIT 30').all(`%${q}%`, req.user.id)
    : db.prepare('SELECT * FROM users WHERE id!=? ORDER BY id DESC LIMIT 30').all(req.user.id);
  res.json(rows.map((u) => userCard(req.user.id, u)));
}));

app.get('/api/user/:id', auth, wrap((req, res) => {
  const u = getUser(+req.params.id);
  if (!u) return res.status(404).json({ error: 'Kullanıcı yok' });
  res.json({
    ...userCard(req.user.id, u),
    followers: db.prepare('SELECT COUNT(*) c FROM follows WHERE followee=?').get(u.id).c,
    followingCount: db.prepare('SELECT COUNT(*) c FROM follows WHERE follower=?').get(u.id).c,
  });
}));

app.post('/api/follow/:id', auth, wrap((req, res) => {
  const id = +req.params.id;
  if (id === req.user.id || !getUser(id)) return res.status(400).json({ error: 'Geçersiz' });
  db.prepare('INSERT OR IGNORE INTO follows(follower,followee) VALUES(?,?)').run(req.user.id, id);
  res.json({ ok: true, mutual: mutual(req.user.id, id) });
}));

app.delete('/api/follow/:id', auth, wrap((req, res) => {
  db.prepare('DELETE FROM follows WHERE follower=? AND followee=?').run(req.user.id, +req.params.id);
  res.json({ ok: true });
}));

// Karşılıklı takipleştiklerin (mesaj / grup / arama için)
app.get('/api/mutuals', auth, wrap((req, res) => {
  const rows = db
    .prepare(
      `SELECT u.* FROM users u
       WHERE u.id IN (SELECT followee FROM follows WHERE follower=?)
         AND u.id IN (SELECT follower FROM follows WHERE followee=?)
       ORDER BY u.username`
    )
    .all(req.user.id, req.user.id);
  res.json(rows.map(publicUser));
}));

// ---------- Sohbetler ----------
function convView(c, meId) {
  const members = db
    .prepare('SELECT u.id,u.username,u.avatar,m.left FROM members m JOIN users u ON u.id=m.user_id WHERE m.conv_id=?')
    .all(c.id);
  const last = db.prepare('SELECT * FROM messages WHERE conv_id=? ORDER BY id DESC LIMIT 1').get(c.id);
  return { id: c.id, type: c.type, name: c.name, members, last, created_by: c.created_by };
}

app.get('/api/convs', auth, wrap((req, res) => {
  const convs = db
    .prepare(
      `SELECT c.* FROM convs c JOIN members m ON m.conv_id=c.id WHERE m.user_id=?
       ORDER BY COALESCE((SELECT MAX(id) FROM messages WHERE conv_id=c.id),0) DESC, c.id DESC`
    )
    .all(req.user.id);
  res.json(convs.map((c) => convView(c, req.user.id)));
}));

function notifyConvChanged(convId) {
  for (const uid of activeMemberIds(convId)) io.to('user:' + uid).emit('convs:changed');
}

app.post('/api/dm/:userId', auth, wrap((req, res) => {
  const other = +req.params.userId;
  if (!getUser(other) || other === req.user.id) return res.status(400).json({ error: 'Geçersiz kullanıcı' });
  if (!mutual(req.user.id, other))
    return res.status(403).json({ error: 'Mesajlaşmak için birbirinizi takip etmelisiniz' });
  const key = [req.user.id, other].sort((a, b) => a - b).join('-');
  let c = db.prepare('SELECT * FROM convs WHERE dm_key=?').get(key);
  if (!c) {
    const r = db.prepare("INSERT INTO convs(type,dm_key,created_by,created_at) VALUES('dm',?,?,?)").run(key, req.user.id, now());
    db.prepare('INSERT INTO members(conv_id,user_id) VALUES(?,?),(?,?)').run(r.lastInsertRowid, req.user.id, r.lastInsertRowid, other);
    c = db.prepare('SELECT * FROM convs WHERE id=?').get(r.lastInsertRowid);
    notifyConvChanged(c.id);
  }
  res.json(convView(c, req.user.id));
}));

app.post('/api/groups', auth, wrap((req, res) => {
  const name = String(req.body.name || '').trim().slice(0, 40);
  const ids = [...new Set((Array.isArray(req.body.members) ? req.body.members : []).map(Number))].filter((i) => Number.isInteger(i) && i !== req.user.id);
  if (!name) return res.status(400).json({ error: 'Grup adı yaz' });
  for (const i of ids) if (!mutual(req.user.id, i)) return res.status(403).json({ error: 'Sadece karşılıklı takipleştiklerini ekleyebilirsin' });
  const r = db.prepare("INSERT INTO convs(type,name,created_by,created_at) VALUES('group',?,?,?)").run(name, req.user.id, now());
  const ins = db.prepare('INSERT INTO members(conv_id,user_id) VALUES(?,?)');
  [req.user.id, ...ids].forEach((i) => ins.run(r.lastInsertRowid, i));
  notifyConvChanged(r.lastInsertRowid);
  res.json(convView(db.prepare('SELECT * FROM convs WHERE id=?').get(r.lastInsertRowid), req.user.id));
}));

app.post('/api/convs/:id/members', auth, wrap((req, res) => {
  const id = +req.params.id;
  const c = db.prepare('SELECT * FROM convs WHERE id=?').get(id);
  const uid = +req.body.userId;
  if (!c || c.type !== 'group' || !isActiveMember(id, req.user.id)) return res.status(403).json({ error: 'Yetkin yok' });
  if (!getUser(uid) || !mutual(req.user.id, uid)) return res.status(403).json({ error: 'Karşılıklı takip gerekli' });
  db.prepare('INSERT INTO members(conv_id,user_id,left) VALUES(?,?,0) ON CONFLICT(conv_id,user_id) DO UPDATE SET left=0').run(id, uid);
  notifyConvChanged(id);
  res.json({ ok: true });
}));

// Gruptan çık: sohbet ve mesajlar SİLİNMEZ
app.post('/api/convs/:id/leave', auth, wrap((req, res) => {
  const id = +req.params.id;
  const c = db.prepare('SELECT type FROM convs WHERE id=?').get(id);
  if (!c || c.type !== 'group') return res.status(400).json({ error: 'Sadece gruptan çıkılabilir' });
  db.prepare('UPDATE members SET left=1 WHERE conv_id=? AND user_id=?').run(id, req.user.id);
  io.to('user:' + req.user.id).emit('convs:changed');
  notifyConvChanged(id);
  res.json({ ok: true });
}));

app.get('/api/convs/:id/messages', auth, wrap((req, res) => {
  const id = +req.params.id;
  if (!isAnyMember(id, req.user.id)) return res.status(403).json({ error: 'Yetkin yok' });
  const before = +req.query.before || 9e15;
  const rows = db
    .prepare(
      `SELECT m.*, u.username, u.avatar FROM messages m JOIN users u ON u.id=m.sender_id
       WHERE m.conv_id=? AND m.id<? ORDER BY m.id DESC LIMIT 50`
    )
    .all(id, before);
  res.json(rows.reverse());
}));

// Yetkisiz kişinin dosyası diske / buluta yazılmasın diye kontrol yüklemeden ÖNCE yapılır
const canPost = (req, res, next) => {
  const id = +req.params.id;
  if (!isActiveMember(id, req.user.id)) return res.status(403).json({ error: 'Bu sohbete mesaj atamazsın' });
  const c = db.prepare('SELECT * FROM convs WHERE id=?').get(id);
  if (c && c.type === 'dm') {
    const other = activeMemberIds(id).find((i) => i !== req.user.id);
    if (other && !mutual(req.user.id, other))
      return res.status(403).json({ error: 'Birbirinizi takip etmiyorsunuz' });
  }
  next();
};

app.post('/api/convs/:id/messages', auth, canPost, upload.single('file'), mirror, wrap((req, res) => {
  const id = +req.params.id;
  const text = String(req.body.text || '').slice(0, 4000);
  let kind = 'text', file = null, fileName = null;
  if (req.file) {
    kind = kindFromMime(req.file.mimetype);
    file = '/uploads/' + req.file.filename;
    fileName = req.file.originalname;
  } else if (!text.trim()) return res.status(400).json({ error: 'Boş mesaj' });
  const r = db
    .prepare('INSERT INTO messages(conv_id,sender_id,kind,text,file,file_name,created_at) VALUES(?,?,?,?,?,?,?)')
    .run(id, req.user.id, kind, text, file, fileName, now());
  const msg = { ...db.prepare('SELECT * FROM messages WHERE id=?').get(r.lastInsertRowid), username: req.user.username, avatar: req.user.avatar };
  for (const uid of activeMemberIds(id)) io.to('user:' + uid).emit('message', msg);
  res.json(msg);
}));

// ---------- Hikayeler (24 saat görünür, dosyalar silinmez) ----------
app.post('/api/stories', auth, upload.single('file'), mirror, wrap((req, res) => {
  if (!req.file) return res.status(400).json({ error: 'Fotoğraf veya video seç' });
  const kind = kindFromMime(req.file.mimetype);
  if (kind !== 'image' && kind !== 'video') return res.status(400).json({ error: 'Sadece fotoğraf/video' });
  db.prepare('INSERT INTO stories(user_id,kind,file,caption,created_at) VALUES(?,?,?,?,?)').run(
    req.user.id, kind, '/uploads/' + req.file.filename, String(req.body.caption || '').slice(0, 200), now()
  );
  res.json({ ok: true });
}));

app.get('/api/stories', auth, wrap((req, res) => {
  const rows = db
    .prepare(
      `SELECT s.*, u.username, u.avatar FROM stories s JOIN users u ON u.id=s.user_id
       WHERE s.created_at>? AND (s.user_id=? OR s.user_id IN (SELECT followee FROM follows WHERE follower=?))
       ORDER BY s.created_at ASC`
    )
    .all(now() - DAY, req.user.id, req.user.id);
  const map = new Map();
  for (const s of rows) {
    if (!map.has(s.user_id)) map.set(s.user_id, { user: { id: s.user_id, username: s.username, avatar: s.avatar }, items: [] });
    map.get(s.user_id).items.push({ id: s.id, kind: s.kind, file: s.file, caption: s.caption, created_at: s.created_at });
  }
  res.json([...map.values()]);
}));

// ---------- Beklenmeyen hatalar (ör. dosya çok büyük) JSON dönsün ----------
app.use((err, req, res, next) => {
  if (res.headersSent) return next(err);
  if (err && err.code === 'LIMIT_FILE_SIZE') return res.status(413).json({ error: 'Dosya çok büyük (en fazla 200 MB)' });
  const status = err && err.status >= 400 && err.status < 500 ? err.status : 500;
  if (status === 500) console.error('Yükleme/istek hatası:', err);
  res.status(status).json({ error: status === 500 ? 'Sunucu hatası (' + describe(err) + ')' : 'Geçersiz istek' });
});

// ---------- Socket.IO: gerçek zamanlı + arama sinyalleşmesi ----------
io.use((socket, next) => {
  const t = socket.handshake.auth && socket.handshake.auth.token;
  const u = typeof t === 'string' && t ? db.prepare('SELECT * FROM users WHERE token=?').get(t) : null;
  if (!u) return next(new Error('unauthorized'));
  socket.user = u;
  next();
});

const calls = new Map(); // callId -> { convId, video, peers: Map(socketId -> {userId, username}) }

function leaveCall(socket) {
  const callId = socket.callId;
  if (!callId) return;
  socket.callId = null;
  const call = calls.get(callId);
  socket.leave('call:' + callId);
  if (!call) return;
  call.peers.delete(socket.id);
  io.to('call:' + callId).emit('call:peer-left', { sid: socket.id });
  if (call.peers.size === 0) {
    calls.delete(callId);
    io.emit('call:ended', { callId });
  }
}

io.on('connection', (socket) => {
  const me = socket.user;
  socket.join('user:' + me.id);

  const ringUser = (callId, call, uid) => {
    const conv = db.prepare('SELECT * FROM convs WHERE id=?').get(call.convId);
    io.to('user:' + uid).emit('call:incoming', {
      callId, convId: call.convId, video: call.video,
      from: { id: me.id, username: me.username },
      convName: conv && conv.type === 'group' ? conv.name : null,
    });
  };

  socket.on('call:start', ({ convId, video }, ack) => {
    if (!isActiveMember(+convId, me.id)) return ack && ack({ error: 'Bu sohbette değilsin' });
    const callId = crypto.randomBytes(8).toString('hex');
    const call = { convId: +convId, video: !!video, peers: new Map() };
    calls.set(callId, call);
    for (const uid of activeMemberIds(+convId)) if (uid !== me.id) ringUser(callId, call, uid);
    ack && ack({ callId });
  });

  // Aramaya birini ekle (karşılıklı takipleştiklerinden)
  socket.on('call:invite', ({ callId, userId }, ack) => {
    const call = calls.get(callId);
    if (!call || !call.peers.has(socket.id)) return ack && ack({ error: 'Aramada değilsin' });
    if (!getUser(+userId) || !mutual(me.id, +userId)) return ack && ack({ error: 'Karşılıklı takip gerekli' });
    ringUser(callId, call, +userId);
    ack && ack({ ok: true });
  });

  socket.on('call:join', ({ callId }, ack) => {
    const call = calls.get(callId);
    if (!call) return ack && ack({ error: 'Arama bitmiş' });
    const peers = [...call.peers].map(([sid, p]) => ({ sid, userId: p.userId, username: p.username }));
    call.peers.set(socket.id, { userId: me.id, username: me.username });
    socket.callId = callId;
    socket.join('call:' + callId);
    socket.to('call:' + callId).emit('call:peer-joined', { sid: socket.id, userId: me.id, username: me.username });
    ack && ack({ peers, video: call.video });
  });

  socket.on('call:leave', () => leaveCall(socket));

  socket.on('signal', ({ to, data }) => {
    io.to(to).emit('signal', { from: socket.id, data });
  });

  socket.on('disconnect', () => leaveCall(socket));
});

// ---------- Veritabanı yedeği (değişiklik varsa her 20 sn + kapanırken) ----------
if (bk.enabled) {
  let last = -1, chain = Promise.resolve();
  const doSnap = async () => {
    try {
      const ch = db.prepare('SELECT total_changes() c').get().c;
      if (ch === last) return;
      const tmp = path.join(DATA_DIR, 'app.db.bak');
      await db.backup(tmp);
      await bk.putFile('app.db', tmp);
      last = ch;
    } catch (e) { console.error('Yedek hatası:', e.message); }
  };
  const snap = () => (chain = chain.then(doSnap));
  snap();
  setInterval(snap, bk.INTERVAL);
  const bye = async () => { await snap(); process.exit(0); };
  process.on('SIGTERM', bye);
  process.on('SIGINT', bye);
  console.log('Bulut yedekleme açık.');
}

server.listen(PORT, '0.0.0.0', () => console.log('Sunucu çalışıyor: ' + PORT));
